const std = @import("std");

pub fn main() !void {
    const INF: u32 = 9999;
    const graph = [_][5]u32{
        [_]u32{ 0, 2, 0, 6, 0 },
        [_]u32{ 2, 0, 3, 8, 5 },
        [_]u32{ 0, 3, 0, 0, 7 },
        [_]u32{ 6, 8, 0, 0, 9 },
        [_]u32{ 0, 5, 7, 9, 0 },
    };
    var dist = [_]u32{ INF, INF, INF, INF, INF };
    var visited = [_]bool{false} ** 5;
    dist[0] = 0;

    for (0..4) |_| {
        var min_dist: u32 = INF;
        var min_idx: u8 = 0;
        for (0..5) |i| {
            if (!visited[i] and dist[i] < min_dist) {
                min_dist = dist[i];
                min_idx = @intCast(i);
            }
        }
        visited[min_idx] = true;
        for (0..5) |i| {
            if (!visited[i] and graph[min_idx][i] != 0 and 
                dist[min_idx] + graph[min_idx][i] < dist[i]) {
                dist[i] = dist[min_idx] + graph[min_idx][i];
            }
        }
    }

    for (0..5) |i| std.debug.print("0->{}: {} ", .{i, dist[i]});
    std.debug.print("\n", .{});
}
